/* From Uiverse.io by mohamedkhire  - Tags: glassmorphism, card, box, transition, card template, cool card */
.__UIV_SCOPE__ .card::before {
  border-radius: 50%;
  width: 7rem;
  height: 7rem;
  top: 20%;
}

.__UIV_SCOPE__ .card::before,
.__UIV_SCOPE__ .card::after {
  content: "";
  background-color: #7090fa4b;
  position: absolute;
  filter: blur(10px);
}

.__UIV_SCOPE__ .cards {
  display: flex;
  gap: 40px;
}

.__UIV_SCOPE__ .cards .red,
.__UIV_SCOPE__ .cards .blue,
.__UIV_SCOPE__ .cards .green {
  width: 200px;
  height: 180px;
  font-family: "CustomFont", Arial, Helvetica, sans-serif;
  font-size: 24px;
  font-weight: 600;
  backdrop-filter: blur(30px);
  background-color: rgba(65, 65, 65, 0.11);
  border: 1px solid rgba(144, 161, 255, 0.171);
}

.__UIV_SCOPE__ .cards .card {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  border-radius: 10px;
  color: rgb(0, 0, 0);
  cursor: pointer;
  transition: 400ms;
}

.__UIV_SCOPE__ .cards .card p.tip {
  font-size: 1em;
  font-weight: 700;
}

.__UIV_SCOPE__ .cards .card p.second-text {
  font-size: 0.7em;
}

.__UIV_SCOPE__ .cards .card:hover {
  transform: scale(1.1, 1.1);
}

.__UIV_SCOPE__ .cards:hover > .card:not(:hover) {
  filter: blur(5px);
  transform: scale(0.9, 0.9);
}
